CREATE TRIGGER [Setup2_insert_trigger] ON [Setup2] FOR INSERT AS
UPDATE [side] SET [sync_row_is_tombstone] = 0, [local_update_peer_key] = 0, [restore_timestamp] = NULL, [update_scope_local_id] = NULL, [last_change_datetime] = GETDATE() FROM [Setup2_tracking] [side] JOIN INSERTED AS [i] ON [side].[IdPost] = [i].[IdPost] AND [side].[Chiave] = [i].[Chiave]
INSERT INTO [Setup2_tracking] ([i].[IdPost], [i].[Chiave], [create_scope_local_id], [local_create_peer_key], [local_create_peer_timestamp], [update_scope_local_id], [local_update_peer_key], [sync_row_is_tombstone], [last_change_datetime], [restore_timestamp]) SELECT [i].[IdPost], [i].[Chiave], NULL, 0, @@DBTS+1, NULL, 0, 0, GETDATE() , NULL FROM INSERTED AS [i] LEFT JOIN [Setup2_tracking] [side] ON [side].[IdPost] = [i].[IdPost] AND [side].[Chiave] = [i].[Chiave] WHERE [side].[IdPost] IS NULL AND [side].[Chiave] IS NULL
